// wht_cuda.cu -- Walsh-Hadamard transform rows on an NVIDIA GPU, textbook vs the 5/6 and 3/4 circuits in the
// per-thread register stage (22 Oct 2026).  UNTESTED ON A GPU when written (no CUDA on the Mac): the
// stage code and the kernels were checked on the CPU through wht_cuda_cpucheck.cpp, which compiles THIS file's
// device code as plain C++ (see the HOST_EMU switch).  The program checks itself before timing and stops on failure.
//
// Kernels (kernels_cuda.h, generated by gen_cuda.py; one FADD / FFMA per circuit line):
//   radix 16: k_tb16 (64 adds), k_g52 (3/4 family, 52 lines), k_g56 (ax-s0 depth 6, 56 lines)
//   radix  8: k_tb8 (24 adds), k_g19 (5/6 step, 19 lines), k_g22 (ax-s0 depth 4, 22 lines)
// Two experiments, every variant in one process, taking turns (9 repeats of >= 0.2 s; best and median printed):
//   "row":  one thread block per row of N floats, rows from global memory (the real use: a batch of rows, e.g. an
//           LLM rotation). N = R^k.  Load the row into shared memory (padded, conflict-free first stage), k register
//           stages of radix R with stride R^s, store.  Reports GB/s and the device-to-device copy GB/s (the roofline).
//   "regs": the register stage alone, applied REP times per thread (the instruction-throughput ceiling: what the
//           op count can buy when nothing else limits).
// Usage: ./wht_cuda check | row | regs | all        Build: nvcc -O3 -std=c++17 -arch=sm_XX wht_cuda.cu -o wht_cuda
#ifndef HOST_EMU
#include <cuda_runtime.h>
#define HD __host__ __device__
#else
#define __device__
#define __forceinline__ inline
#define __global__
#define __fmaf_rn(a, b, c) fmaf((a), (b), (c))
#define HD
#endif
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <vector>
#include <algorithm>
#include "kernels_cuda.h"

typedef void (*kfun)(float *);
// padded shared-memory index: one spare word per 32 makes the stride-R first stage conflict-free
HD inline int pad(int i) { return i + (i >> 5); }

// one register stage for thread t: R values at base + d*S, transformed in registers, written back in place
template <int R, int KID>
__device__ __forceinline__ void stage(float *sm, int t, int S) {
  int h = t / S, l = t - h * S, base = h * S * R + l;
  float v[R];
#pragma unroll
  for (int d = 0; d < R; d++) v[d] = sm[pad(base + d * S)];
  if constexpr (R == 16) { if constexpr (KID == 0) k_tb16(v); else if constexpr (KID == 1) k_g52(v); else k_g56(v); }
  else                    { if constexpr (KID == 0) k_tb8(v);  else if constexpr (KID == 1) k_g19(v); else k_g22(v); }
#pragma unroll
  for (int d = 0; d < R; d++) sm[pad(base + d * S)] = v[d];
}

#ifndef HOST_EMU
template <int N, int R, int KID>
__global__ void __launch_bounds__(N / R) wht_row(const float *__restrict__ in, float *__restrict__ out) {
  __shared__ float sm[N + N / 32];
  const int T = N / R, t = threadIdx.x;
  const float *src = in + (size_t)blockIdx.x * N;
  float *dst = out + (size_t)blockIdx.x * N;
#pragma unroll
  for (int i = t; i < N; i += T) sm[pad(i)] = src[i];
  __syncthreads();
#pragma unroll
  for (int S = 1; S < N; S *= R) {
    stage<R, KID>(sm, t, S);
    __syncthreads();
  }
#pragma unroll
  for (int i = t; i < N; i += T) dst[i] = sm[pad(i)];
}
template <int R, int KID, int REP>
__global__ void wht_regs(const float *__restrict__ in, float *__restrict__ out) {
  size_t g = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
  float v[R];
#pragma unroll
  for (int d = 0; d < R; d++) v[d] = in[g * R + d];
#pragma unroll 1
  for (int r = 0; r < REP; r++) {
    if constexpr (R == 16) { if constexpr (KID == 0) k_tb16(v); else if constexpr (KID == 1) k_g52(v); else k_g56(v); }
    else                    { if constexpr (KID == 0) k_tb8(v);  else if constexpr (KID == 1) k_g19(v); else k_g22(v); }
  }
#pragma unroll
  for (int d = 0; d < R; d++) out[g * R + d] = v[d];
}

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) { printf("CUDA error %s at %s:%d\n", cudaGetErrorString(e_), __FILE__, __LINE__); exit(1); } } while (0)
static const char *KNAME[2][3] = {{"tb8", "g19", "g22d4"}, {"tb16", "g52", "g56d6"}};

static void ref_wht(double *x, int n) {
  for (int h = 1; h < n; h <<= 1)
    for (int i = 0; i < n; i += 2 * h)
      for (int j = i; j < i + h; j++) { double a = x[j], b = x[j + h]; x[j] = a + b; x[j + h] = a - b; }
}
typedef void (*launch_fn)(const float *, float *, int rows);
template <int N, int R, int KID> static void L_row(const float *a, float *b, int rows) { wht_row<N, R, KID><<<rows, N / R>>>(a, b); }
template <int R, int KID, int REP> static void L_regs(const float *a, float *b, int threads) { wht_regs<R, KID, REP><<<threads / 256, 256>>>(a, b); }

struct Var { const char *name; launch_fn f; };
template <int N, int R> static std::vector<Var> rowvars() {
  int r = R == 16 ? 1 : 0;
  return {{KNAME[r][0], L_row<N, R, 0>}, {KNAME[r][1], L_row<N, R, 1>}, {KNAME[r][2], L_row<N, R, 2>}};
}

static int check_rows(const char *label, std::vector<Var> vars, int N, int rows) {
  size_t n = (size_t)N * rows;
  std::vector<float> h(n), o(n);
  for (size_t i = 0; i < n; i++) h[i] = (float)((rand() % 2001) - 1000) / 1000.0f;
  float *a, *b;
  CK(cudaMalloc(&a, n * 4)); CK(cudaMalloc(&b, n * 4));
  CK(cudaMemcpy(a, h.data(), n * 4, cudaMemcpyHostToDevice));
  int ok = 1;
  for (auto &v : vars) {
    CK(cudaMemset(b, 0, n * 4));
    v.f(a, b, rows); CK(cudaGetLastError()); CK(cudaDeviceSynchronize());
    CK(cudaMemcpy(o.data(), b, n * 4, cudaMemcpyDeviceToHost));
    double emax = 0, rmax = 0;
    for (int r = 0; r < rows; r++) {
      std::vector<double> x(h.begin() + (size_t)r * N, h.begin() + (size_t)(r + 1) * N);
      ref_wht(x.data(), N);
      for (int i = 0; i < N; i++) { double e = fabs(x[i] - o[(size_t)r * N + i]); if (!(e <= emax)) emax = e; rmax = std::max(rmax, fabs(x[i])); }
    }
    int pass = emax / rmax < 1e-5;
    ok &= pass;
    printf("CHECK %s N=%d %-6s rel err %.3e %s\n", label, N, v.name, emax / rmax, pass ? "PASS" : "FAIL");
  }
  // broken copy: flip one output sign of the first variant's result; the comparison must catch it
  {
    std::vector<double> x(h.begin(), h.begin() + N); ref_wht(x.data(), N);
    vars[0].f(a, b, rows); CK(cudaDeviceSynchronize()); CK(cudaMemcpy(o.data(), b, (size_t)N * 4, cudaMemcpyDeviceToHost));
    o[N / 2 + 1] = -o[N / 2 + 1];
    double emax = 0, rmax = 0;
    for (int i = 0; i < N; i++) { emax = std::max(emax, fabs(x[i] - o[i])); rmax = std::max(rmax, fabs(x[i])); }
    int caught = !(emax / rmax < 1e-5) || x[N / 2 + 1] == 0;
    printf("CHECK %s N=%d broken copy %s\n", label, N, caught ? "CAUGHT (good)" : "NOT CAUGHT");
    ok &= caught;
  }
  CK(cudaFree(a)); CK(cudaFree(b));
  return ok;
}
static int check_regs(void) { // REP = 1: one register stage = an N=R transform per thread
  int ok = 1;
  const int threads = 1 << 12;
  for (int R : {8, 16}) {
    size_t n = (size_t)threads * R;
    std::vector<float> h(n), o(n);
    for (size_t i = 0; i < n; i++) h[i] = (float)((rand() % 17) - 8);
    float *a, *b; CK(cudaMalloc(&a, n * 4)); CK(cudaMalloc(&b, n * 4));
    CK(cudaMemcpy(a, h.data(), n * 4, cudaMemcpyHostToDevice));
    launch_fn F[3];
    if (R == 8) { F[0] = L_regs<8, 0, 1>; F[1] = L_regs<8, 1, 1>; F[2] = L_regs<8, 2, 1>; }
    else { F[0] = L_regs<16, 0, 1>; F[1] = L_regs<16, 1, 1>; F[2] = L_regs<16, 2, 1>; }
    for (int k = 0; k < 3; k++) {
      F[k](a, b, threads); CK(cudaDeviceSynchronize());
      CK(cudaMemcpy(o.data(), b, n * 4, cudaMemcpyDeviceToHost));
      long bad = 0;
      for (int t = 0; t < threads; t++) {
        std::vector<double> x(h.begin() + (size_t)t * R, h.begin() + (size_t)(t + 1) * R);
        ref_wht(x.data(), R);
        for (int i = 0; i < R; i++) bad += (x[i] != (double)o[(size_t)t * R + i]);
      }
      printf("CHECK regs R=%d %-6s exact on integers: %ld wrong %s\n", R, KNAME[R == 16][k], bad, bad ? "FAIL" : "PASS");
      ok &= !bad;
    }
    CK(cudaFree(a)); CK(cudaFree(b));
  }
  return ok;
}

// ---- timing: programs take turns; each repeat >= 0.2 s of back-to-back launches, timed with events ----
struct Stat { std::vector<double> ms_per_call; };
static void time_turns(const char *title, std::vector<Var> vars, const float *a, float *b, int arg, double units, const char *uname, double bytes) {
  cudaEvent_t e0, e1; CK(cudaEventCreate(&e0)); CK(cudaEventCreate(&e1));
  int nv = vars.size();
  std::vector<long> calls(nv);
  for (int k = 0; k < nv; k++) { // calibrate
    long c = 1;
    for (;;) {
      CK(cudaEventRecord(e0));
      for (long i = 0; i < c; i++) vars[k].f(a, b, arg);
      CK(cudaEventRecord(e1)); CK(cudaEventSynchronize(e1));
      float ms; CK(cudaEventElapsedTime(&ms, e0, e1));
      if (ms >= 200) break;
      c = ms < 12 ? c * 8 : (long)(c * 220.0 / ms) + 1;
    }
    calls[k] = c;
  }
  std::vector<std::vector<double>> rep(nv);
  printf("## %s (9 repeats of >= 0.2 s, programs take turns)\n", title);
  for (int r = 0; r < 9; r++)
    for (int jj = 0; jj < nv; jj++) {
      int k = (jj + r) % nv;
      CK(cudaEventRecord(e0));
      for (long i = 0; i < calls[k]; i++) vars[k].f(a, b, arg);
      CK(cudaEventRecord(e1)); CK(cudaEventSynchronize(e1));
      float ms; CK(cudaEventElapsedTime(&ms, e0, e1));
      double per = ms * 1e6 / calls[k] / units; // ns per unit
      rep[k].push_back(per);
      printf("rep %d %-8s %.5f ns/%s\n", r, vars[k].name, per, uname);
    }
  CK(cudaGetLastError());
  double base = 0;
  for (int k = 0; k < nv; k++) {
    std::vector<double> s = rep[k]; std::sort(s.begin(), s.end());
    double gbs = bytes > 0 ? bytes / (s[4] * units) : 0; // bytes per call / ns per call = GB/s
    if (k == 0) base = s[4];
    printf("RESULT %s %-8s best %.5f median %.5f ns/%s%s ratio-vs-%s %.4f", title, vars[k].name, s[0], s[4], uname,
           "", vars[0].name, s[4] / base);
    if (bytes > 0) printf("  %.1f GB/s", gbs);
    printf("\n");
  }
  CK(cudaEventDestroy(e0)); CK(cudaEventDestroy(e1));
}
static double copy_gbs(size_t bytes) {
  float *a, *b; CK(cudaMalloc(&a, bytes)); CK(cudaMalloc(&b, bytes));
  cudaEvent_t e0, e1; CK(cudaEventCreate(&e0)); CK(cudaEventCreate(&e1));
  float best = 1e30f;
  for (int r = 0; r < 9; r++) {
    CK(cudaEventRecord(e0));
    for (int i = 0; i < 20; i++) CK(cudaMemcpyAsync(b, a, bytes, cudaMemcpyDeviceToDevice));
    CK(cudaEventRecord(e1)); CK(cudaEventSynchronize(e1));
    float ms; CK(cudaEventElapsedTime(&ms, e0, e1)); best = std::min(best, ms / 20);
  }
  CK(cudaFree(a)); CK(cudaFree(b));
  return 2.0 * bytes / (best * 1e6); // read + write
}
template <int N, int R> static void bench_row(size_t total_floats) {
  int rows = (int)(total_floats / N);
  float *a, *b; CK(cudaMalloc(&a, (size_t)rows * N * 4)); CK(cudaMalloc(&b, (size_t)rows * N * 4));
  CK(cudaMemset(a, 0, (size_t)rows * N * 4));
  char t[96]; snprintf(t, sizeof t, "row N=%d radix=%d rows=%d", N, R, rows);
  time_turns(t, rowvars<N, R>(), a, b, rows, (double)rows * N, "point", 8.0 * rows * N);
  CK(cudaFree(a)); CK(cudaFree(b));
}
template <int R, int REP> static void bench_regs(int threads) {
  float *a, *b; CK(cudaMalloc(&a, (size_t)threads * R * 4)); CK(cudaMalloc(&b, (size_t)threads * R * 4));
  CK(cudaMemset(a, 0, (size_t)threads * R * 4));
  std::vector<Var> v = {{KNAME[R == 16][0], L_regs<R, 0, REP>}, {KNAME[R == 16][1], L_regs<R, 1, REP>}, {KNAME[R == 16][2], L_regs<R, 2, REP>}};
  char t[96]; snprintf(t, sizeof t, "regs R=%d REP=%d threads=%d", R, REP, threads);
  time_turns(t, v, a, b, threads, (double)threads * REP, "block", 0);
  CK(cudaFree(a)); CK(cudaFree(b));
}

int main(int argc, char **argv) {
  const char *mode = argc > 1 ? argv[1] : "all";
  cudaDeviceProp p; CK(cudaGetDeviceProperties(&p, 0));
  int clk_khz = 0; cudaDeviceGetAttribute(&clk_khz, cudaDevAttrClockRate, 0);  /* fix 22 Oct: CUDA 13 dropped cudaDeviceProp.clockRate */
  printf("# wht_cuda on %s, sm_%d%d, %d SMs, %.0f MHz, %d-bit bus, L2 %d KB\n", p.name, p.major, p.minor,
         p.multiProcessorCount, clk_khz / 1e3, p.memoryBusWidth, p.l2CacheSize / 1024);
  srand(7);
  int ok = check_regs();
  ok &= check_rows("row", rowvars<256, 16>(), 256, 64);
  ok &= check_rows("row", rowvars<4096, 16>(), 4096, 16);
  ok &= check_rows("row", rowvars<512, 8>(), 512, 64);
  ok &= check_rows("row", rowvars<4096, 8>(), 4096, 16);
  printf("ALL %s\n", ok ? "PASS" : "FAIL");
  if (!ok) return 1;
  if (!strcmp(mode, "check")) return 0;
  size_t tot = (size_t)1 << 26; // 64 Mi floats = 256 MiB per buffer: past every L2
  if (!strcmp(mode, "row") || !strcmp(mode, "all")) {
    printf("COPY device-to-device %.1f GB/s (read + write, 256 MiB)\n", copy_gbs(tot * 4));
    bench_row<256, 16>(tot); bench_row<4096, 16>(tot); bench_row<512, 8>(tot); bench_row<4096, 8>(tot);
    bench_row<256, 16>((size_t)1 << 20); bench_row<4096, 16>((size_t)1 << 20); // 4 MiB: fits in L2 on A100 / L4
  }
  if (!strcmp(mode, "regs") || !strcmp(mode, "all")) {
    int th = p.multiProcessorCount * 2048;
    bench_regs<16, 256>(th); bench_regs<8, 256>(th);
  }
  return 0;
}
#endif
